// TEST ONLY: requires the isolated database generated by tools/benchmark.
import { chromium, expect } from "@playwright/test";
import { spawn, spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
const root = process.cwd();
const dir = path.join(root, ".local", "MILLION_GUI_TEST_ONLY_" + Date.now());
fs.mkdirSync(dir, { recursive: true });
const db = path.join(dir, "tokenscope.sqlite3");
fs.copyFileSync(
  process.env.TOKENSCOPE_TEST_MILLION_DB ??
    path.join(root, ".local/million-test-20261009.sqlite3"),
  db,
);
const init = spawnSync(
  "python",
  [
    "-c",
    "import sqlite3,sys; c=sqlite3.connect(sys.argv[1]); c.execute(\"UPDATE app_settings SET value='false' WHERE key='fx_enabled'\"); c.commit()",
    db,
  ],
  { encoding: "utf8" },
);
if (init.status !== 0) throw Error(init.stderr);
const child = spawn(
  process.env.TOKENSCOPE_TEST_EXE ??
    path.join(root, "artifacts/windows/installed-final/tokenscope.exe"),
  [],
  {
    windowsHide: true,
    stdio: "ignore",
    env: {
      ...process.env,
      TOKENSCOPE_TEST_MODE: "1",
      TOKENSCOPE_DATA_DIR: dir,
      CODEX_HOME: path.join(dir, "missing"),
      TOKENSCOPE_CODEX_BIN: path.join(dir, "missing.exe"),
      WEBVIEW2_USER_DATA_FOLDER: path.join(dir, "webview-profile"),
      WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS:
        "--remote-debugging-port=9232 --remote-debugging-address=127.0.0.1",
    },
  },
);
let browser;
try {
  for (let n = 0; n < 30; n++) {
    try {
      browser = await chromium.connectOverCDP("http://127.0.0.1:9232");
      break;
    } catch {
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
  if (!browser) throw Error("WebView unavailable");
  const page = browser.contexts().flatMap((c) => c.pages())[0];
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await expect(page.locator(".metric strong").first()).toHaveAttribute(
    "title",
    "110,000,000",
    { timeout: 30000 },
  );
  await expect(page.getByText("开发验证模式", { exact: false })).toBeVisible();
  await page.evaluate(() => {
    const started = performance.now();
    window.__millionPromise = window.__TAURI_INTERNALS__
      .invoke("read_dashboard", { filter: { grain: "minute" } })
      .then((d) => ({ d, query_ms: performance.now() - started }));
  });
  const clicked = Date.now();
  await page.getByRole("button", { name: "设置与数据源", exact: true }).click();
  await expect(
    page.getByRole("heading", { name: "Provider 能力" }),
  ).toBeVisible();
  const navigation_ms = Date.now() - clicked;
  const { d, query_ms } = await page.evaluate(() => window.__millionPromise);
  if (
    d.totals.total !== "110000000" ||
    d.snapshots !== 1000000 ||
    d.events.length !== 500 ||
    d.turns.length !== 500 ||
    !d.turns_truncated ||
    d.timeline.length > 720
  )
    throw Error("Million IPC mismatch");
  if (
    d.timeline.reduce((n, g) => n + BigInt(g.totals.total), 0n) !== 110000000n
  )
    throw Error("Timeline totals mismatch");
  if (navigation_ms > 3000) throw Error("GUI navigation blocked during query");
  await page.getByRole("button", { name: /^总览/ }).click();
  const update = spawnSync(
    "python",
    [
      "-c",
      "import sqlite3,json,sys; c=sqlite3.connect(sys.argv[1]); d=json.dumps(dict(input=200,cached=100,output=20,reasoning=4,total=220)); c.execute(\"UPDATE usage_events SET delta=? WHERE id='TEST_ONLY_EVENT0000000'\",(d,)); c.commit()",
      db,
    ],
    { encoding: "utf8" },
  );
  if (update.status !== 0) throw Error(update.stderr);
  const refreshStarted = Date.now();
  await page.evaluate(() => {
    window.__refreshStorm = setInterval(
      () =>
        void window.__TAURI_INTERNALS__.invoke("plugin:event|emit", {
          event: "usage-updated",
          payload: null,
        }),
      500,
    );
  });
  try {
    await expect(page.locator(".metric strong").first()).toHaveAttribute(
      "title",
      "110,000,110",
      { timeout: 10000 },
    );
  } finally {
    await page.evaluate(() => clearInterval(window.__refreshStorm));
  }
  const continuous_refresh_ms = Date.now() - refreshStarted;
  const exportStarted = Date.now();
  const exported = await page.evaluate(() =>
    window.__TAURI_INTERNALS__.invoke("export_usage", { filter: null }),
  );
  const export_ms = Date.now() - exportStarted;
  if (exported.rows !== 1000000 || exported.totals.total !== "110000110")
    throw Error("Million export truncated or inaccurate");
  const parsed = spawnSync(
    "python",
    [
      "-c",
      "import csv,sys; n=0; total=0; f=open(sys.argv[1],encoding='utf-8-sig',newline=''); rows=csv.DictReader(f); \nfor r in rows: n+=1; total+=int(r['total_tokens_decimal']) if r['confirmed']=='true' else 0\nassert n==1000000 and total==110000110; print(n,total)",
      path.join(exported.directory, "usage.csv"),
    ],
    { encoding: "utf8" },
  );
  if (parsed.status !== 0) throw Error(parsed.stderr);
  if (errors.length) throw Error(errors.join("\n"));
  const report = {
    test_only: true,
    installed_release: true,
    events: d.snapshots,
    query_ms,
    navigation_ms,
    continuous_refresh_ms,
    exact_totals: true,
    csv_rows: exported.rows,
    export_ms,
    frontend_errors: errors.length,
  };
  fs.writeFileSync(
    path.join(dir, "report.json"),
    JSON.stringify(report, null, 2),
  );
  console.log(JSON.stringify(report));
} finally {
  if (browser) await browser.close();
  child.kill();
  if (child.exitCode === null && child.signalCode === null)
    await new Promise((r) => child.once("exit", r));
}
